  const state=document.createElement('p');state.className='review-state';state.textContent=latest?'Comparison complete · results are shown beside this draft':activeSpec.missing_inputs.length?'Needs clarification':activeSpec.unsupported_requests.length?'Unsupported request · review limitation':'Ready for your review';card.append(state);
  const details=document.createElement('details');details.className='review-details';const summaryLine=document.createElement('summary');summaryLine.textContent='Inputs, assumptions & model details';details.append(summaryLine);
  const source=field=>activeSpec.assumptions.find(item=>item.field===field)?.origin??'engine default';
